// Phase 40 demo journeys, run D2: demo preparation (open items and bank line; the PDFs are uploaded in the workspace).
// Generated by scripts/fixtures/gen_phase40_demo_journeys.py. SYNTHETIC documents, MOCK SAP data. Scope x_695068_bcfa.
(function() {
    // MOCK SAP reference data for this run: two open invoices of Nilgiri Rubber Compounds Ltd.
    var cust = new GlideRecord('x_695068_bcfa_customer');
    if (!cust.get('name', 'Nilgiri Rubber Compounds Ltd')) { gs.info('BCFA_DEMO40 ABORTED: customer Nilgiri Rubber Compounds Ltd not found (run the demo reset first)'); return; }
    var items = [['ARINV-D2-01', 50000, '2026-09-30'], ['ARINV-D2-02', 30000, '2026-10-02']], out = [];
    items.forEach(function(it) {
        var oi = new GlideRecord('x_695068_bcfa_ar_open_item');
        if (oi.get('item_number', it[0])) { out.push(it[0] + ' exists'); return; }
        oi.initialize();
        oi.setValue('item_number', it[0]);
        oi.setValue('customer', cust.getUniqueValue());
        oi.setValue('company_code', cust.getValue('company_code'));
        oi.setValue('currency', 'INR');
        oi.setValue('invoice_amount', it[1]);
        oi.setValue('open_amount', it[1]);
        oi.setValue('due_date', it[2]);
        oi.setValue('status', 'open');
        oi.insert();
        out.push(it[0] + ' created');
    });
    // The bank statement line: the cash arrives before the advice, without a customer.
    var pay = new GlideRecord('x_695068_bcfa_payment');
    var paymentSysId;
    if (pay.get('bank_reference', 'NRC-PAY-26-D2')) { paymentSysId = pay.getUniqueValue(); out.push('bank line exists'); }
    else {
        paymentSysId = new ArDomainService().intakePayment({ bankReference: 'NRC-PAY-26-D2', currency: 'INR', amount: 78400, bankAccount: 'DEMO-D2',
            source: 'bank_statement', idempotencyKey: 'PH40-DEMO-AR-D2' }).paymentSysId;
        out.push('bank line NRC-PAY-26-D2 INR 78,400 created');
    }
    gs.info('BCFA_DEMO40 prep D2: ' + out.join('; ') + '. Upload AP_INV_D2_DEMO_NATIVE.pdf (AP Invoice) and AR_REMIT_D2_DEMO_NATIVE.pdf (Payment Advice) in Document Intake.');
})();
